class algo {
    constructor() {
        this.objects = [];
    }
    createObject(name) {
        const obj = { name: name, refCount: 1 };
        this.objects.push(obj);
        return obj;
    }
    mark() {
        this.objects.forEach(obj => {
            if (obj.refCount > 0) {
                obj.marked = true;
            }
        });
    }
    sweep() {
        this.objects = this.objects.filter(obj => obj.marked);
    }
    collectGarbage() {
        this.mark();
        this.sweep();
    }
    prints() {
        return this.objects
    }
